    public static void main(String[] args) {
        String src = "public class A { public static void main(String[] args) {"
                + " \"Hello single %s!\".formatted(\"world\");"
                + " \"\"\"\n Hello multiple %s!\n \"\"\".formatted(\"world\");"
                + " } }";
        ParserConfiguration pc = new ParserConfiguration();
        pc.setLanguageLevel(ParserConfiguration.LanguageLevel.JAVA_17);
        CompilationUnit cu = new JavaParser(pc).parse(src).getResult().get();
        ReflectionTypeSolver solver = new ReflectionTypeSolver(false);
        new VoidVisitorAdapter<>() {
            public void visit(MethodCallExpr n, Object arg) {
                super.visit(n, arg);
                try {
                    SymbolReference<ResolvedMethodDeclaration> solved = JavaParserFacade.get(solver).solve(n);
                    System.out.println("Could solve: " + n + " as " + solved.getCorrespondingDeclaration().getQualifiedSignature());
                } catch (Exception e) {
                    System.err.println("Could not solve: " + n + " -> " + e);
                }
            }
        }.visit(cu.getTypes(), null);
    }
}
